import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import { normalizeErrorStackOptions } from './dist/error-options.js';
import { processStackString, processStackFrames } from './dist/error-stack.js';
assert.equal(normalizeErrorStackOptions(null), undefined);
const o=normalizeErrorStackOptions({mode:'string',stripInternalFrames:'node',maxStackLines:2});
const stack='Error: x\n at node:internal/test\n at /tmp/a.js:1:2';
assert.equal(processStackString(stack,o),'Error: x');
assert.equal(processStackFrames(stack,o).length,2);
for (const mode of ['off','string','frames']) { const s=new SuperJSON({errorStack:{mode}});s.allowErrorProps('stack','stackFrames');const e=new Error('x');e.stack=stack;const r=s.serialize(e);assert.equal(r.meta.values[0],mode==='off'?'Error':`Error/${mode==='string'?'stack':'frames'}`);if(mode!=='string')assert(!('stack' in r.json));if(mode!=='frames')assert(!('stackFrames' in r.json)); }
const s=new SuperJSON({errorStack:{mode:'string',includeCauses:'deep',maxCauseDepth:2,sanitizeMessage:true}});s.allowErrorProps('stack'); const a=new Error('http://example.com'),b=new Error('x@y.com');a.cause=b;b.cause=a;let seen;s.registerErrorStackProcessor('Error',x=>{seen=x;return x});const r=s.serialize(a);assert.equal(r.json.message,'[redacted]');assert.equal(r.json.cause.message,'[redacted]');assert(!('cause' in r.json.cause));assert(seen.stack);assert(s.parse(s.stringify(a)).cause instanceof Error);
const ag=new AggregateError([1,new Date(0)],'x');const restored=s.parse(s.stringify(ag));assert(restored.errors[1] instanceof Date);
console.log('Option, ordering, cycles, hooks and aggregate checks passed');
EOF
